func TestGettersMcpGatewayServerList(t *testing.T) {
	t.Run("GetItems", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &McpGatewayServerList{}
		var expected []*McpGatewayServer
		obj.Items = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetItems(), "getter should return the property value")
	})

	t.Run("GetItems_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &McpGatewayServerList{}
		obj.Items = nil

		// Act & Assert
		assert.Nil(t, obj.GetItems(), "getter should return nil when property is nil")
	})

	t.Run("GetItems_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *McpGatewayServerList
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetItems() // Should return zero value
	})

	t.Run("GetGatewayEnabled", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &McpGatewayServerList{}
		var expected bool
		obj.GatewayEnabled = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetGatewayEnabled(), "getter should return the property value")
	})

	t.Run("GetGatewayEnabled_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *McpGatewayServerList
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetGatewayEnabled() // Should return zero value
	})

}

